using Unity.Entities;
using Unity.Mathematics;

// components: plain structs with data, no behaviour
public struct Velocity : IComponentData { public float3 Value; }
public struct Health   : IComponentData { public float Value; }

// an entity is just an ID (Index + Version) that components hang on
Entity e = entityManager.CreateEntity(typeof(Velocity), typeof(Health));
entityManager.SetComponentData(e, new Health { Value = 100f });

// archetype A = { LocalTransform, Velocity }
// one 16 KiB chunk of archetype A, an array per component:
//   Entity[]          e0  e1  e2  ...  eN
//   LocalTransform[]  t0  t1  t2  ...  tN
//   Velocity[]        v0  v1  v2  ...  vN
//
// a move system reads LocalTransform[] and Velocity[] front to back;
// add Health to e1 -> e1 is copied into a chunk of archetype
// B = { LocalTransform, Velocity, Health }, eN fills the hole in A

using Unity.Burst;
using Unity.Entities;
using Unity.Transforms;

[BurstCompile]
public partial struct MoveSystem : ISystem
{
    [BurstCompile]
    public void OnUpdate(ref SystemState state)
    {
        float dt = SystemAPI.Time.DeltaTime;
        // main thread: every chunk whose archetype has both components
        foreach (var (transform, velocity) in
                 SystemAPI.Query<RefRW<LocalTransform>, RefRO<Velocity>>())
            transform.ValueRW.Position += velocity.ValueRO.Value * dt;
    }
}

[BurstCompile]
public partial struct PoisonJob : IJobEntity
{
    public float DeltaTime;
    // ref = read-write, in = read-only; the query is built from these parameters
    void Execute(ref Health health, in Poison poison)
        => health.Value -= poison.DamagePerSecond * DeltaTime;
}

// in PoisonSystem.OnUpdate (an ISystem):
new PoisonJob { DeltaTime = SystemAPI.Time.DeltaTime }.ScheduleParallel();
// no handle, no Complete(): the call reads and updates state.Dependency

[BurstCompile]
public ___ struct ShieldRegenJob : IJobEntity
{
    public float DeltaTime;
    void Execute(___ Shield shield, ___ ShieldRegen regen)
        => shield.Value += regen.PerSecond * DeltaTime;
}

// in ShieldSystem.OnUpdate:
new ShieldRegenJob { DeltaTime = SystemAPI.Time.DeltaTime }.___();

// MoveSystem:   ref LocalTransform, in Velocity   -> writes LocalTransform
// AimSystem:    in LocalTransform, ref Aim        -> reads LocalTransform
//
// Entities knows the read/write sets of both systems, so AimSystem's
// state.Dependency already contains MoveSystem's job:
//   MoveJob (workers) ──► AimJob (workers) ──► ... ──► render reads results
// nobody calls Complete() in between

